pub fn ignored_by_rules(
    path: &str,
    is_dir: bool,
    rules: &[IgnoreRule],
    case_insensitive: bool,
) -> bool {
    let mut ignored = false;
    for rule in rules {
        if matches_ignore_pattern(path, is_dir, &rule.pattern, case_insensitive) {
            ignored = !rule.negated;
        }
    }
    ignored
}

